    BuiltinControllersStep((BuiltinControllerChoice, ObjectRef)),
    ControllerStep((int, Option<Message>, Option<ObjectRef>)),
    ScheduleControllerReconcileStep((int, ObjectRef)),
    RestartControllerStep(int),
    DisableCrashStep(int),
